"""Render the self-contained One-Day Pricing reviewer dashboard."""
from __future__ import annotations
import html
import json
from typing import Any, Mapping, Sequence
from utils import number

def _e(value: object) -> str:
    return html.escape(str(value or ''), quote=True)

def _safe_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=True).replace('</', '<\\/')

def _money(value: object, currency: str='USD') -> str:
    try:
        amount = number(value)
    except Exception:
        return '-'
    symbol = '$' if currency == 'USD' else currency + ' '
    return f'{symbol}{amount:,.0f}'

def _pct(value: object, digits: int=1) -> str:
    try:
        return f'{100 * number(value):.{digits}f}%'
    except Exception:
        return '-'

def _mult(value: object) -> str:
    try:
        return f'{number(value):.2f}x'
    except Exception:
        return '-'

def render_dashboard(metadata: Mapping[str, Any], positions: Sequence[Mapping[str, Any]], results: Sequence[Mapping[str, Any]], portfolios: Sequence[Mapping[str, Any]], sensitivities: Sequence[Mapping[str, Any]], exceptions: Sequence[Mapping[str, Any]], checks: Sequence[Mapping[str, Any]], evidence: Mapping[str, Any], market_evaluation: Sequence[Mapping[str, Any]], briefs: Sequence[Mapping[str, Any]]) -> str:
    base_rows = [row for row in results if row.get('scenario_id') == 'base']
    base_port = next((row for row in portfolios if row.get('scenario_id') == 'base'), {})
    status_counts = {status: sum((row.get('status') == status for row in base_rows)) for status in ['DEMO_PURSUABLE', 'DEMO_REVIEW', 'DEMO_DECLINE', 'NO_QUOTE']}
    base_table = ''.join((f"<tr><td><button class='link' data-pos='{_e(row['position_id'])}'>{_e(row['display_name'])}</button></td><td>{_e(row['status'])}</td><td>{_pct(row['ask_nav_fraction'])}</td><td>{_pct(row['max_nav_fraction'])}</td><td>{_money(row['ask_closing_seller_payment'], row['currency'])}</td><td>{_money(row['closing_unfunded'], row['currency'])}</td><td>{_pct(row['ask_irr'])}</td><td>{_mult(row['buyer_money_multiple'])}</td><td>{_e(row['status_reason'])}</td></tr>" for row in base_rows)) or "<tr><td colspan='9'>Evidence-only mode: no simulated price was produced.</td></tr>"
    check_table = ''.join((f"<tr><td>{_e(r['check_id'])}</td><td class='{_e(r['status'].lower())}'>{_e(r['status'])}</td><td>{_e(r['actual'])}</td><td>{_e(r['expected'])}</td><td>{_e(r['source'])}</td><td>{_e(r.get('reason', ''))}</td></tr>" for r in checks))
    market_table = ''.join((f'<tr><td>{_e(r.get('split'))}</td><td>{_e(r.get('count'))}</td><td>{_pct(r.get('baseline_mae'))}</td><td>{_pct(r.get('model_mae'))}</td><td>{_e(r.get('model_beats_baseline'))}</td><td>{_pct(r.get('model_bias'))}</td></tr>' for r in market_evaluation)) or "<tr><td colspan='6'>Synthetic market experiment not run.</td></tr>"
    fingerprint_table = ''.join((f"<tr><td>{_e(r['path'])}</td><td>{_e(r['bytes'])}</td><td class='hash'>{_e(r['sha256'])}</td></tr>" for r in metadata.get('input_fingerprints', [])))
    css = '\n    :root{--bg:#07111c;--p:#0d1b2a;--p2:#10243a;--line:#29435d;--text:#edf4fb;--muted:#99aec1;--accent:#74c9ff;--good:#7fe2b0;--warn:#ffd18a;--bad:#ff9d9d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,Segoe UI,Arial,sans-serif;line-height:1.45}header{padding:28px 4vw 20px;background:#0a1b2d;border-bottom:1px solid var(--line)}h1{margin:4px 0 8px;font-size:32px}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--accent);font-weight:700}.muted{color:var(--muted)}.tabs{display:flex;gap:8px;padding:12px 4vw;position:sticky;top:0;background:#07111cf2;border-bottom:1px solid var(--line);z-index:5;overflow:auto}.tab,select{background:#0d1b2a;color:var(--text);border:1px solid var(--line);border-radius:8px;padding:8px 11px}.tab.active{border-color:var(--accent);color:var(--accent)}main{padding:22px 4vw 60px}.view{display:none}.view.active{display:block}.panel{background:var(--p);border:1px solid var(--line);border-radius:13px;padding:18px;margin-bottom:16px}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px}.kpi{background:var(--p2);border:1px solid #203a54;border-radius:10px;padding:13px}.kpi span{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.07em}.kpi strong{display:block;font-size:23px;margin-top:4px}.table{overflow:auto;border:1px solid var(--line);border-radius:9px}table{width:100%;border-collapse:collapse;min-width:850px}th,td{padding:9px 10px;border-bottom:1px solid var(--line);font-size:12px;text-align:left;vertical-align:top}th{background:#10243a;color:#bfd0df}.link{border:0;background:none;color:var(--accent);cursor:pointer;padding:0}.callout{border-left:4px solid var(--accent);padding:12px 15px;background:#0a2033;border-radius:8px}.pass,.good{color:var(--good)}.fail,.bad{color:var(--bad)}.warn{color:var(--warn)}.hash{font-family:Consolas,monospace;font-size:10px}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}ul{padding-left:20px}@media(max-width:850px){.grid2{grid-template-columns:1fr}.tabs{position:static}}@media print{body{background:white;color:#111}.tabs{display:none}.panel{border:1px solid #bbb;background:white}.muted{color:#444}}\n    '
    payload = _safe_json({'positions': list(positions), 'results': list(results), 'portfolios': list(portfolios), 'sensitivities': list(sensitivities), 'exceptions': list(exceptions), 'briefs': list(briefs)})
    base_status = _e(base_port.get('status', 'EVIDENCE_ONLY'))
    html_text = f"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><link rel='icon' href='data:,'><title>One-Day Pricing</title><style>{css}</style></head><body>\n<header><div class='eyebrow'>LP secondary pricing demonstration | {_e(metadata.get('population'))} | policy {_e(metadata.get('policy_version'))}</div><h1>One-Day Pricing</h1><p class='muted'>Hypothetical seller positions over controlled fund data. Buyer ceilings come from declared future cash flows and return hurdles. Synthetic results are not observed secondary transactions or AlpInvest prices.</p></header>\n<div class='tabs'><button class='tab active' data-view='summary'>Transaction</button><button class='tab' data-view='positions'>Positions</button><button class='tab' data-view='scenarios'>Scenarios & Funding</button><button class='tab' data-view='evidence'>Evidence & QC</button><button class='tab' data-view='market'>Synthetic Market Test</button></div>\n<main>\n<section id='summary' class='view active'><div class='kpis'><div class='kpi'><span>Base portfolio status</span><strong>{base_status}</strong></div><div class='kpi'><span>Seller ask</span><strong>{_pct(base_port.get('portfolio_ask_nav_fraction'))}</strong></div><div class='kpi'><span>Buyer ceiling</span><strong>{_pct(base_port.get('portfolio_max_nav_fraction'))}</strong></div><div class='kpi'><span>Ask IRR</span><strong>{_pct(base_port.get('ask_irr'))}</strong></div><div class='kpi'><span>Pursuable</span><strong>{status_counts['DEMO_PURSUABLE']}</strong></div><div class='kpi'><span>Review / no quote</span><strong>{status_counts['DEMO_REVIEW'] + status_counts['NO_QUOTE']}</strong></div></div><div class='panel'><h2>Base case positions</h2><div class='table'><table><thead><tr><th>Position</th><th>Status</th><th>Ask / NAV</th><th>Buyer ceiling / NAV</th><th>Closing seller payment</th><th>Closing unfunded</th><th>Buyer IRR</th><th>Money multiple</th><th>Reason</th></tr></thead><tbody>{base_table}</tbody></table></div></div><div class='callout'>Seller ask and buyer ceiling are different numbers. The ceiling solves the declared buyer return requirement. It is not a market-clearing-price claim.</div></section>\n<section id='positions' class='view'><div class='panel'><label>Position <select id='position-select'></select></label></div><div id='position-detail'></div></section>\n<section id='scenarios' class='view'><div class='panel'><label>Scenario <select id='scenario-select'><option>base</option><option>downside</option><option>upside</option></select></label></div><div id='scenario-detail'></div></section>\n<section id='evidence' class='view'><div class='grid2'><div class='panel'><h2>Quality controls</h2><div class='table'><table><thead><tr><th>Check</th><th>Status</th><th>Actual</th><th>Expected</th><th>Source</th><th>Reason</th></tr></thead><tbody>{check_table}</tbody></table></div></div><div class='panel'><h2>Data boundaries</h2><ul><li>Parent records are read-only inputs.</li><li>Integrated numeric positions use neutral display names because their fund IDs combine source identities with generated completion.</li><li>Observed named-source records receive no simulated investment recommendation.</li><li>Language-model text cannot change numeric prices.</li></ul></div></div><div class='panel'><h2>Consumed input fingerprints</h2><div class='table'><table><thead><tr><th>Path</th><th>Bytes</th><th>SHA-256</th></tr></thead><tbody>{fingerprint_table}</tbody></table></div></div></section>\n<section id='market' class='view'><div class='panel'><h2>Synthetic comparable-price experiment</h2><p class='muted'>This experiment tests software and model separation on fictional clearing prices. It does not establish real-market accuracy.</p><div class='table'><table><thead><tr><th>Split</th><th>N</th><th>Median baseline MAE</th><th>Ridge MAE</th><th>Model beats baseline</th><th>Model bias</th></tr></thead><tbody>{market_table}</tbody></table></div></div></section>\n</main><script>const data={payload};const $=s=>document.querySelector(s);const all=s=>[...document.querySelectorAll(s)];const pct=v=>v===null||v===undefined||v===''?'-':(100*Number(v)).toFixed(1)+'%';const money=(v,c='USD')=>v===null||v===undefined||v===''?'-':(c==='USD'?'$':c+' ')+Number(v).toLocaleString(undefined,{{maximumFractionDigits:0}});function rowFor(pid,sc){{return data.results.find(x=>x.position_id===pid&&x.scenario_id===sc)}}function initPositions(){{const sel=$('#position-select');sel.innerHTML=data.positions.map(p=>`<option value="${{p.position_id}}">${{p.display_name}}</option>`).join('');renderPosition();}}function renderPosition(){{const pid=$('#position-select').value;const p=data.positions.find(x=>x.position_id===pid);const r=rowFor(pid,'base');if(!p||!r){{$('#position-detail').innerHTML='';return;}}const sens=data.sensitivities.filter(x=>x.position_id===pid&&x.scenario_id==='base').map(x=>`<tr><td>${{pct(x.hurdle_rate)}}</td><td>${{pct(x.max_nav_fraction)}}</td><td>${{money(x.max_reference_price,r.currency)}}</td></tr>`).join('');const b=data.briefs.find(x=>x.position_id===pid);$('#position-detail').innerHTML=`<div class='grid2'><div class='panel'><h2>${{p.display_name}}</h2><div class='kpis'><div class='kpi'><span>Ask</span><strong>${{pct(r.ask_nav_fraction)}}</strong></div><div class='kpi'><span>Ceiling</span><strong>${{pct(r.max_nav_fraction)}}</strong></div><div class='kpi'><span>Ask IRR</span><strong>${{pct(r.ask_irr)}}</strong></div><div class='kpi'><span>Unfunded</span><strong>${{money(r.closing_unfunded,r.currency)}}</strong></div></div><p>${{r.status}}: ${{r.status_reason}}</p></div><div class='panel'><h3>Dates and true-up</h3><p>Reference ${{r.reference_date}} | quote ${{r.quote_date}} | close ${{r.closing_date}}</p><p>Actual true-up ${{money(r.actual_settlement_adjustment,r.currency)}}; forecast close true-up ${{money(r.forecast_settlement_adjustment,r.currency)}}.</p><p>Reference NAV ${{money(r.reference_nav,r.currency)}}; closing economic NAV ${{money(r.closing_economic_nav,r.currency)}}.</p></div></div><div class='panel'><h3>Hurdle sensitivity</h3><div class='table'><table><thead><tr><th>Buyer hurdle</th><th>Ceiling / NAV</th><th>Max reference price</th></tr></thead><tbody>${{sens}}</tbody></table></div></div>${{b?`<div class='panel'><h3>Brief</h3><p>${{b.summary||''}}</p></div>`:''}}`;}}function renderScenario(){{const sc=$('#scenario-select').value;const p=data.portfolios.find(x=>x.scenario_id===sc);const rows=data.results.filter(x=>x.scenario_id===sc).map(x=>`<tr><td>${{x.display_name}}</td><td>${{x.status}}</td><td>${{pct(x.ask_nav_fraction)}}</td><td>${{pct(x.max_nav_fraction)}}</td><td>${{pct(x.ask_irr)}}</td><td>${{money(x.future_calls,x.currency)}}</td><td>${{money(x.future_distributions,x.currency)}}</td></tr>`).join('');$('#scenario-detail').innerHTML=`<div class='kpis'><div class='kpi'><span>Portfolio ask</span><strong>${{p?pct(p.portfolio_ask_nav_fraction):'-'}}</strong></div><div class='kpi'><span>Portfolio ceiling</span><strong>${{p?pct(p.portfolio_max_nav_fraction):'-'}}</strong></div><div class='kpi'><span>Portfolio IRR</span><strong>${{p?pct(p.ask_irr):'-'}}</strong></div><div class='kpi'><span>Future calls</span><strong>${{p?money(p.future_calls,p.currency):'-'}}</strong></div></div><div class='panel'><div class='table'><table><thead><tr><th>Position</th><th>Status</th><th>Ask</th><th>Ceiling</th><th>IRR</th><th>Calls</th><th>Distributions</th></tr></thead><tbody>${{rows}}</tbody></table></div></div>`;}}all('.tab').forEach(b=>b.addEventListener('click',()=>{{all('.tab').forEach(x=>x.classList.remove('active'));all('.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+b.dataset.view).classList.add('active');}}));all('.link').forEach(b=>b.addEventListener('click',()=>{{all('.tab').forEach(x=>x.classList.toggle('active',x.dataset.view==='positions'));all('.view').forEach(x=>x.classList.toggle('active',x.id==='positions'));$('#position-select').value=b.dataset.pos;renderPosition();}}));$('#position-select')?.addEventListener('change',renderPosition);$('#scenario-select')?.addEventListener('change',renderScenario);initPositions();renderScenario();</script></body></html>"""
    return html_text
